mapper.select:
SELECT order_id, tenant_id, listing_id, store_id, platform, marketplace, platform_order_no,
       buyer_name, customer_id, country_code, shipping_address, currency, total_amount,
       tax_amount, shipping_amount, discount_amount, status, payment_status,
       fulfillment_status, risk_level, profit_margin, order_date, created_at, updated_at
FROM oms_sales_order
WHERE tenant_id = #{tenantId}
  AND platform = #{platform}
  AND buyer_name = #{buyerName}
  AND created_at >= #{createdAfter}
ORDER BY created_at DESC

mapper.update:
UPDATE oms_order_refund
SET reason = #{reason}, refund_amount = #{refundAmount}, refund_type = #{refundType},
    status = #{status}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND refund_id = #{refundId}

mapper.select:
SELECT refund_id, tenant_id, order_id, reason, refund_amount, refund_type, status, created_at, updated_at
FROM oms_order_refund
WHERE tenant_id = #{tenantId} AND refund_id = #{refundId}

SELECT entry_id, tenant_id, buyer_name, reason, created_at
FROM oms_buyer_blacklist
WHERE tenant_id = #{tenantId} AND entry_id = #{entryId}

mapper.update:
UPDATE oms_pms_risk_alert
SET status = #{status}
WHERE alert_id = #{alertId}

mapper.select:
SELECT sync_id, tenant_id, platform, sync_type, status, synced_count, failed_count,
       error_message, started_at, completed_at
FROM oms_order_sync_log
WHERE tenant_id = #{tenantId}

    AND platform = #{platform}

ORDER BY started_at DESC

SELECT strategy_id, tenant_id, strategy_type, name, description, rules, enabled, priority,
       created_at, updated_at
FROM oms_order_strategy
WHERE tenant_id = #{tenantId}

    AND strategy_type = #{strategyType}

ORDER BY priority ASC, created_at DESC

mapper.update:
UPDATE oms_order_strategy
SET name = #{name}, description = #{description}, rules = #{rules},
    enabled = #{enabled}, priority = #{priority}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND strategy_id = #{strategyId}
